--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_RISK_OBJECT_BK__K0)) as HUB_RISK_OBJECT_HK,
        RISK_CLASS as RISK_CLASS_CODE,
        UNIQUE_IDENTIFICATION_DESCRIPTION as IDENTIFICATION_REFERENCE,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_pv') }}
    where HUB_RISK_OBJECT_K0__EMIT
)), hashed as (select *,
        case when RISK_CLASS_CODE is not null or IDENTIFICATION_REFERENCE is not null
             then md5(upper(coalesce(RISK_CLASS_CODE::varchar,'') || '||' || coalesce(IDENTIFICATION_REFERENCE::varchar,'')))
        end as SAT_RISK_OBJECT_CORE_HASHDIFF
    from feeders)

select * from hashed
where HUB_RISK_OBJECT_HK is not null
  and SAT_RISK_OBJECT_CORE_HASHDIFF is not null
